def final_temperature(requested):
    if requested is None:
        return 0.7
    if 0 <= requested <= 2:
        return requested
    return 0.7

def average_per_call(total_tokens, n_calls):
    if n_calls == 0:
        return 0.0
    return round(total_tokens / n_calls, 2)

def batches_needed(n_prompts, batch_size):
    return (n_prompts + batch_size - 1) // batch_size

