exercicios.explicacao_md:
In chat APIs (OpenAI and Anthropic) the history is a **list of dicts** — each message has a `role` and a `content`:

```python
messages = [
    {"role": "system", "content": "Be brief."},
    {"role": "user", "content": "Hi!"},
]
messages[1]["content"]   # "Hi!" — index the list, then read the key

# counter dict: create the key with 0 the first time, then add
counts = {}
for color in ["blue", "green", "blue"]:
    if color not in counts:
        counts[color] = 0
    counts[color] += 1
# {"blue": 2, "green": 1}
```

These two patterns — navigating a nested dict and counting with a dict — solve half of all log and chat-history analysis. Keep them close.

exercicios.solucao_referencia:
def count_roles(messages):
    counts = {}
    for msg in messages:
        role = msg["role"]
        if role not in counts:
            counts[role] = 0
        counts[role] += 1
    return counts

def last_question(messages):
    result = ""
    for msg in messages:
        if msg["role"] == "user":
            result = msg["content"]
    return result

def frequency(text):
    counts = {}
    for word in text.split():
        word = word.lower()
        if word not in counts:
            counts[word] = 0
        counts[word] += 1
    return counts

def dedupe(ids):
    seen = set()
    result = []
    for item in ids:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def rebuild(questions, answers):
    messages = []
    for question, answer in zip(questions, answers):
        messages.append({"role": "user", "content": question})
        messages.append({"role": "assistant", "content": answer})
    return messages

def purge_empty(history):
    for msg in history[:]:
        if not msg["content"].strip():
            history.remove(msg)
    return history

def tokens_by_model(records):
    totals = {}
    for rec in records:
        model = rec.get("model", "unknown")
        tokens = rec.get("tokens", 0)
        totals[model] = totals.get(model, 0) + tokens
    return totals

def get_score(pair):
    return pair[1]

def rank(names, scores):
    pairs = list(zip(names, scores))
    ordered = sorted(pairs, key=get_score, reverse=True)
    ranking = []
    for name, score in ordered:
        ranking.append(name)
    return ranking

def build_request(prompt, model="mock-4", temperature=0.7, **extras):
    req = {
        "model": model,
        "temperature": temperature,
        "messages": [{"role": "user", "content": prompt}],
    }
    req.update(extras)
    return req

def sort_by_cost(models):
    ordered = sorted(models, key=lambda m: m["cost_per_1k"])
    names = []
    for m in ordered:
        names.append(m["name"])
    return names

def apply_to_batch(func, texts):
    results = []
    for text in texts:
        results.append(func(text))
    return results

def log_params(**params):
    parts = []
    for key in sorted(params):
        parts.append(f"{key}={params[key]}")
    return " ".join(parts)

def record(event, history=None):
    if history is None:
        history = []
    history.append(event)
    return history

def record_usage(model, *tokens):
    if not tokens:
        raise ValueError("no tokens provided")
    for t in tokens:
        if not isinstance(t, int):
            raise TypeError(f"invalid token: {t!r}")
    return {"model": model, "calls": len(tokens), "total": sum(tokens)}

